    { en: "Strain into cup.", zh: "滤进杯。", speaker: "mom", type: "casual" },
    { en: "Spicy warm.", zh: "辣暖。", speaker: "mom", type: "casual" },
    { en: "Sip slow.", zh: "慢喝。", speaker: "mom", type: "momSoft" },
    { en: "Warms you up.", zh: "驱寒。", speaker: "mom", type: "casual" }
